cd /workspaces/semio && cat > /tmp/test-mcp-host.html << 'HOSTEOF'
<!DOCTYPE html>
<html>
<head>
<title>MCP App Test Host</title>
<style>
body { font-family: monospace; padding: 20px; }
#log { white-space: pre-wrap; background: #f0f0f0; padding: 10px; max-height: 400px; overflow: auto; }
iframe { width: 800px; height: 600px; border: 2px solid blue; }
</style>
</head>
<body>
<h2>MCP App Test Host</h2>
<div id="log"></div>
<br/>
<iframe id="app"></iframe>
<script>
const log = (msg) => {
  document.getElementById('log').textContent += new Date().toISOString().substring(11,23) + ' ' + msg + '\n';
  console.log(msg);
};

window.addEventListener('message', (event) => {
  const data = event.data;
  if (!data || !data.jsonrpc) return;
  log('RECV: ' + JSON.stringify(data).substring(0, 500));

  // Handle ui/initialize request
  if (data.method === 'ui/initialize') {
    log('Responding to ui/initialize with host info');
    const response = {
      jsonrpc: '2.0',
      id: data.id,
      result: {
        protocolVersion: '2026-01-26',
        hostInfo: { name: 'test-host', version: '1.0.0' },
        hostCapabilities: {},
        hostContext: { theme: 'light' }
      }
    };
    event.source.postMessage(response, '*');
    log('SENT: ' + JSON.stringify(response).substring(0, 500));

    // After a short delay, send a fake tool result
    setTimeout(() => {
      const toolResult = {
        jsonrpc: '2.0',
        method: 'ui/notifications/tool-result',
        params: {
          content: [{
            type: 'text',
            text: JSON.stringify({
              points: [{guid:'p1', id:'piece-1', u:0, v:0, status:'default'}, {guid:'p2', id:'piece-2', u:5, v:3, status:'added'}],
              lines: [{guid:'l1', sourceU:0, sourceV:0, targetU:5, targetV:3, status:'default'}],
              capabilities: {pieceSelection: true, connectionSelection: true},
              kitArtifacts: {designs: [{guid:'d1', name:'Test Design'}], types: [{guid:'t1', name:'Wall'}], ports: []}
            })
          }]
        }
      };
      event.source.postMessage(toolResult, '*');
      log('SENT tool-result');
    }, 1000);
  }

  // Handle ui/notifications/initialized
  if (data.method === 'ui/notifications/initialized') {
    log('App initialized successfully!');
  }

