cd /workspaces/semio && node -e "
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Collect console messages
  const consoleLogs = [];
  page.on('console', (msg) => {
    consoleLogs.push({ type: msg.type(), text: msg.text() });
  });

  // Collect page errors
  const pageErrors = [];
  page.on('pageerror', (error) => {
    pageErrors.push(error.message);
  });

  try {
    // Navigate to the test host
    await page.goto('http://localhost:9876/test-host.html', { timeout: 10000 });

    // Wait for the iframe to load
    await page.waitForTimeout(3000);

    // Check the log div for host messages
    const logText = await page.textContent('#log');
    console.log('=== HOST LOG ===');
    console.log(logText);

    // Get iframe handle  
    const frame = page.frame({ url: /mcp-app/ }) || page.frames()?.[1];
    if (frame) {
      console.log('\\n=== IFRAME FOUND ===');
      const iframeContent = await frame.content();
      console.log('Iframe HTML length:', iframeContent.length);

      // Check visible text
      const bodyText = await frame.evaluate(() => document.body?.innerText?.substring(0, 500));
      console.log('Iframe visible text:', bodyText);
    } else {
      console.log('\\n=== FRAMES ===');
      for (const f of page.frames()) {
        console.log('Frame:', f.url(), f.name());
      }
    }

    console.log('\\n=== CONSOLE LOGS ===');
    for (const log of consoleLogs) {
      console.log(log.type + ':', log.text);
    }

    console.log('\\n=== PAGE ERRORS ===');
    for (const err of pageErrors) {
      console.log('ERROR:', err);
    }
  } catch (e) {
    console.error('Test error:', e.message);
  } finally {
    await browser.close();
  }
})();
" 2>&1

